-- ChewCheckers Complete Supabase Schema & Initial Data Migration

DROP TABLE IF EXISTS meal_food_items CASCADE;
DROP TABLE IF EXISTS nutrition_scores CASCADE;
DROP TABLE IF EXISTS meals CASCADE;
DROP TABLE IF EXISTS lunchbox_presets CASCADE;
DROP TABLE IF EXISTS parent_student CASCADE;
DROP TABLE IF EXISTS students CASCADE;
DROP TABLE IF EXISTS classes CASCADE;
DROP TABLE IF EXISTS schools CASCADE;
DROP TABLE IF EXISTS messages CASCADE;
DROP TABLE IF EXISTS holidays CASCADE;
DROP TABLE IF EXISTS users CASCADE;

CREATE TABLE users (
  id BIGSERIAL PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  email VARCHAR(150) UNIQUE NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role VARCHAR(20) NOT NULL DEFAULT 'PARENT',
  address VARCHAR(500),
  mobile_number VARCHAR(30),
  profile_picture_path VARCHAR(255),
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE schools (
  id BIGSERIAL PRIMARY KEY,
  name VARCHAR(200) NOT NULL,
  address TEXT,
  academic_year VARCHAR(20),
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE classes (
  id BIGSERIAL PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  grade VARCHAR(20) NOT NULL,
  section VARCHAR(10) NOT NULL,
  join_code VARCHAR(10) UNIQUE NOT NULL,
  school_id BIGINT REFERENCES schools(id) ON DELETE SET NULL,
  teacher_id BIGINT REFERENCES users(id) ON DELETE SET NULL,
  is_active BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE students (
  id BIGSERIAL PRIMARY KEY,
  student_code VARCHAR(20) UNIQUE NOT NULL,
  name VARCHAR(100) NOT NULL,
  gender VARCHAR(10),
  date_of_birth DATE,
  blood_group VARCHAR(5),
  height_cm NUMERIC(5,2),
  weight_kg NUMERIC(5,2),
  roll_number VARCHAR(20),
  school_id BIGINT REFERENCES schools(id) ON DELETE SET NULL,
  class_id BIGINT REFERENCES classes(id) ON DELETE SET NULL,
  box_length NUMERIC(5,2),
  box_width NUMERIC(5,2),
  box_depth NUMERIC(5,2),
  box_volume NUMERIC(8,2),
  box_shape VARCHAR(50),
  box_compartments INT,
  daily_calories INT,
  daily_protein INT,
  daily_carbs INT,
  daily_fat INT,
  daily_fiber INT,
  lunch_calories INT,
  lunch_protein INT,
  lunch_carbs INT,
  lunch_fat INT,
  lunch_fiber INT,
  is_active BOOLEAN NOT NULL DEFAULT true
);

CREATE TABLE parent_student (
  id BIGSERIAL PRIMARY KEY,
  parent_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  relationship VARCHAR(20) NOT NULL DEFAULT 'MOTHER',
  is_primary BOOLEAN NOT NULL DEFAULT true,
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (parent_id, student_id)
);

CREATE TABLE lunchbox_presets (
  id BIGSERIAL PRIMARY KEY,
  preset_name VARCHAR(100) NOT NULL,
  brand VARCHAR(100),
  student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  user_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  length_cm NUMERIC(5,2) NOT NULL,
  width_cm NUMERIC(5,2) NOT NULL,
  depth_cm NUMERIC(5,2) NOT NULL,
  capacity_ml NUMERIC(7,2) NOT NULL,
  compartments INT NOT NULL DEFAULT 1,
  shape VARCHAR(50) DEFAULT 'RECTANGULAR',
  material VARCHAR(50),
  is_default BOOLEAN NOT NULL DEFAULT false,
  created_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE meals (
  id BIGSERIAL PRIMARY KEY,
  student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  meal_date DATE NOT NULL,
  status VARCHAR(40) NOT NULL DEFAULT 'PRE_MEAL_UPLOADED',
  pre_meal_image_url VARCHAR(500),
  post_meal_image_url VARCHAR(500),
  uploaded_by_parent BIGINT REFERENCES users(id) ON DELETE SET NULL,
  uploaded_by_teacher BIGINT REFERENCES users(id) ON DELETE SET NULL,
  box_length NUMERIC(5,2),
  box_width NUMERIC(5,2),
  box_height NUMERIC(5,2),
  lunchbox_preset_id BIGINT,
  lunchbox_preset_name VARCHAR(100),
  created_at TIMESTAMPTZ DEFAULT NOW(),
  UNIQUE (student_id, meal_date)
);

CREATE TABLE meal_food_items (
  id BIGSERIAL PRIMARY KEY,
  meal_id BIGINT NOT NULL REFERENCES meals(id) ON DELETE CASCADE,
  food_name VARCHAR(150) NOT NULL,
  quantity VARCHAR(100),
  calories NUMERIC(8,2) NOT NULL,
  protein_g NUMERIC(6,2) NOT NULL,
  carbs_g NUMERIC(6,2) NOT NULL,
  fat_g NUMERIC(6,2) NOT NULL,
  fiber_g NUMERIC(6,2) NOT NULL,
  leftover_percentage NUMERIC(5,2) DEFAULT 0,
  confidence_score NUMERIC(5,2) DEFAULT 0.95
);

CREATE TABLE nutrition_scores (
  id BIGSERIAL PRIMARY KEY,
  meal_id BIGINT NOT NULL REFERENCES meals(id) ON DELETE CASCADE,
  student_id BIGINT NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  score NUMERIC(5,2) NOT NULL,
  classification VARCHAR(20) NOT NULL,
  lunch_calorie_target NUMERIC(8,2),
  lunch_protein_target NUMERIC(8,2),
  total_consumed_calories NUMERIC(8,2),
  total_consumed_protein_g NUMERIC(8,2),
  total_consumed_carbs_g NUMERIC(8,2),
  total_consumed_fat_g NUMERIC(8,2),
  total_consumed_fiber_g NUMERIC(8,2),
  calculated_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE messages (
  id BIGSERIAL PRIMARY KEY,
  sender_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  receiver_id BIGINT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  message_text TEXT NOT NULL,
  sent_at TIMESTAMPTZ DEFAULT NOW()
);

CREATE TABLE holidays (
  id BIGSERIAL PRIMARY KEY,
  date DATE NOT NULL,
  name VARCHAR(150) NOT NULL,
  type VARCHAR(50) DEFAULT 'PUBLIC'
);

ALTER TABLE users ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for users" ON users FOR ALL USING (true) WITH CHECK (true);
ALTER TABLE schools ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for schools" ON schools FOR ALL USING (true) WITH CHECK (true);
ALTER TABLE classes ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for classes" ON classes FOR ALL USING (true) WITH CHECK (true);
ALTER TABLE students ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for students" ON students FOR ALL USING (true) WITH CHECK (true);
ALTER TABLE parent_student ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for parent_student" ON parent_student FOR ALL USING (true) WITH CHECK (true);
ALTER TABLE lunchbox_presets ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for lunchbox_presets" ON lunchbox_presets FOR ALL USING (true) WITH CHECK (true);
ALTER TABLE meals ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for meals" ON meals FOR ALL USING (true) WITH CHECK (true);
ALTER TABLE meal_food_items ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for meal_food_items" ON meal_food_items FOR ALL USING (true) WITH CHECK (true);
ALTER TABLE nutrition_scores ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for nutrition_scores" ON nutrition_scores FOR ALL USING (true) WITH CHECK (true);
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for messages" ON messages FOR ALL USING (true) WITH CHECK (true);
ALTER TABLE holidays ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Allow all for holidays" ON holidays FOR ALL USING (true) WITH CHECK (true);

